/** YC26 Church Games: the printed timetable per category (organiser's PDF, adjusted 12 Nov 2026).
 *  One list of slot start times per category (the day is not evenly spaced: lunch, warm-ups),
 *  the slot of each knockout round, and the real venue court numbers (X Park PJ South map).
 *  Group games get their slot/court from migration 0051 (generated by scripts/yc26-plan.mjs). */
import type { SlotClock } from './timetable'

const fmt = (t: number) => `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`
const run = (start: string, step: number, n: number): string[] => {
  const [h, m] = start.split(':').map(Number)
  return Array.from({ length: n }, (_, i) => fmt(h * 60 + m + i * step))
}

const badminton = (courts: number[]): Pick<SlotClock, 'times' | 'roundSlots' | 'roundCourts'> => ({
  // 9 group slots (25 min game + 5 min between), lunch 13:35-15:00, then the knockouts
  times: [...run('09:00', 30, 9), '15:15', '15:50', '16:25', '16:55'],
  roundSlots: { 'Quarter-final': [10, 10, 10, 10], Playoff: [10, 10], 'Semi-final': [11, 11], 'Third place': [12], Final: [13] },
  roundCourts: {
    'Quarter-final': courts.slice(0, 4), Playoff: courts.slice(0, 2), 'Semi-final': courts.slice(0, 2),
    'Third place': courts.slice(0, 1), Final: courts.slice(0, 1),
  },
})

export const YC26_CLOCKS: Record<string, SlotClock> = {
  // captain ball (the hub code itself), one court, 15 min games every 20 min
  YC26: {
    start: '09:00', every: 20, sport: 'captainball', cb: true, courts: [2], lunch: '12:00 – 13:25',
    times: [...run('09:00', 20, 6), '13:30', '13:50', '14:10', '14:30', '14:50', '15:10'],
  },
  BMMD: { start: '09:00', every: 30, sport: 'badminton', courts: [2, 3, 4, 5], lunch: '13:35 – 15:00', ...badminton([2, 3, 4, 5]) },
  BMXD: { start: '09:00', every: 30, sport: 'badminton', courts: [6, 7], lunch: '13:35 – 15:00', ...badminton([6, 7]) },
  // pickleball: 12 group slots of 20 min (09:00-12:55), lunch 13:00-14:25
  PBMD: {
    start: '09:00', every: 20, sport: 'pickleball', courts: [2, 3], lunch: '13:00 – 14:25',
    times: [...run('09:00', 20, 12), '14:30', '14:55', '15:25'],
    roundSlots: { 'Semi-final': [13, 13], 'Third place': [14], Final: [15] },
    roundCourts: { 'Semi-final': [2, 3], 'Third place': [2], Final: [2] },
  },
  PBXD: {
    start: '09:00', every: 20, sport: 'pickleball', courts: [1], lunch: '13:00 – 14:25',
    times: [...run('09:00', 20, 12), '14:30', '14:55'],
    roundSlots: { 'Third place': [13], Final: [14] },
    roundCourts: { 'Third place': [1], Final: [1] },
  },
}
